head.script:
scwin.onpageload = function () {
    dlt_a.setJSON([
        { "item" : "노트북", "amount" : "14500000" },
        { "item" : "모니터", "amount" : "6400000" }
    ]);
};

// excelFormatter 로 지정하는 사용자 정의 함수 : excelFormat(#,##0.00) 과 구별되는 표시 서식 0.000 을 반환한다
scwin.getExcelFormat = function (colId) {
    return "0.000";
};

// advancedExcelDownload 실행 + 서버로 전송된 Header / Body 금액 Column 의 excelFormat 출력
scwin.btn_download_onclick = function () {
    let sBody = "";
    let fnSubmit = HTMLFormElement.prototype.submit;
    HTMLFormElement.prototype.submit = function () {
        let objInput = this.querySelector("input[name=xmlValue]");
        if (sBody === "" && objInput) {
            sBody = objInput.value;
        }
        return fnSubmit.apply(this, arguments);
    };
    try {
        grd_a.advancedExcelDownload({ "fileName" : "grid_excelFormatter", "extension" : "xlsx", "useDataFormat" : "true", "useHeaderDataFormat" : "true" });
    } finally {
        HTMLFormElement.prototype.submit = fnSubmit;
    }
    scwin.setReturnValue("Header hAmount Column 전송 excelFormat : " + scwin.getSentAttr(sBody, "hAmount", "excelFormat"));
    scwin.setReturnValue("Body amount Column 전송 excelFormat : " + scwin.getSentAttr(sBody, "amount", "excelFormat"));
};

// 전송 XML 에서 id 로 Column 여는 태그를 찾아 속성값을 읽는다
scwin.getSentAttr = function (sBody, sColId, sAttr) {
    let nId = sBody.indexOf(' id="' + sColId + '"');
    if (nId < 0) {
        return "(미전달)";
    }
    let nStart = sBody.lastIndexOf("<w2:column", nId);
    let sTag = sBody.substring(nStart, sBody.indexOf(">", nId));
    let objVal = sTag.match(new RegExp(" " + sAttr + "=\"([^\"]*)\""));
    return objVal ? objVal[1] : "(없음)";
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
